/* TRML 競速練習：答案比對（學生頁的範例模式與 Apps Script 共用同一份）
 *
 * 答案表的寫法（questions 工作表的 answer 欄）：
 *   1009                一般數字
 *   2017/2018           分數；學生寫 2017/2018 或 4034/4036 都算對（數值相等）
 *   3√2   2+√3   4π     根號、圓周率；學生可打 √ 或 sqrt，π 或 pi
 *   (1,2)               有序數對：依序逐項比對
 *   set:1,3,5           不計順序的多個答案
 *   甲|A                用 | 分隔多個可接受的寫法
 * 學生答案尾端的單位（度、°、公分、cm、個、種……）會先去掉再比。
 */
(function (root) {
  'use strict';

  function toHalfWidth(s) {
    s = String(s == null ? '' : s)
      .replace(/²/g, '^2').replace(/³/g, '^3');
    if (s.normalize) s = s.normalize('NFKC');
    return s;
  }

  function normalize(s) {
    s = toHalfWidth(s).trim().toLowerCase();
    s = s.replace(/根號/g, '√').replace(/或|及|和|；|;/g, ',');
    s = s.replace(/[\s　]+/g, '')
      .replace(/[×＊·⋅]/g, '*')
      .replace(/÷/g, '/')
      .replace(/[−–—‒－]/g, '-')
      .replace(/，|、/g, ',')
      .replace(/（/g, '(').replace(/）/g, ')')
      .replace(/π/g, 'pi')
      .replace(/√/g, 'sqrt')
      .replace(/sqrt\{/g, 'sqrt(').replace(/\}/g, ')').replace(/\{/g, '(');
    // 去掉尾端單位
    s = s.replace(/(%|％|平方公分|立方公分|平方公尺|公分|公尺|公里|cm\^?[23]?|度|°|個|種|人|元|分鐘|分|秒|條|塊|次|天|歲|題|組|根|張|頁|位|顆|隻|輛|本|支|台)+$/, '');
    // 開頭的「x=」「答:」之類
    s = s.replace(/^(答[:：]?|ans[:：]?)/, '');
    s = s.replace(/^[a-z]=/, '');
    return s;
  }

  // ---- 數值解析：+ - * / ^、括號、sqrt、pi、隱含乘法（3sqrt2、2pi、2(3)）
  function evaluate(src, env) {
    var s = src, i = 0;
    env = env || {};
    function peek() { return s[i]; }
    function eat(c) { if (s[i] === c) { i++; return true; } return false; }
    function fail() { throw new Error('parse'); }

    function parseExpr() {
      var v = parseTerm();
      for (;;) {
        if (eat('+')) v += parseTerm();
        else if (eat('-')) v -= parseTerm();
        else return v;
      }
    }
    function startsAtom() {
      var c = peek();
      return c !== undefined && (/[0-9.(a-z]/.test(c));
    }
    function parseTerm() {
      var v = parseUnary();
      for (;;) {
        if (eat('*')) v *= parseUnary();
        else if (eat('/')) { var d = parseUnary(); v /= d; }
        else if (startsAtom()) v *= parsePower(); // 隱含乘法
        else return v;
      }
    }
    function parseUnary() {
      if (eat('-')) return -parseUnary();
      if (eat('+')) return parseUnary();
      return parsePower();
    }
    function parsePower() {
      var b = parseAtom();
      if (eat('^')) { var e = parseUnary(); return Math.pow(b, e); }
      return b;
    }
    function parseAtom() {
      var c = peek();
      if (c === '(') { i++; var v = parseExpr(); if (!eat(')')) fail(); return v; }
      if (s.substr(i, 4) === 'sqrt') {
        i += 4;
        var a;
        if (peek() === '(') { i++; a = parseExpr(); if (!eat(')')) fail(); }
        else a = parsePower();
        if (a < 0) fail();
        return Math.sqrt(a);
      }
      if (s.substr(i, 2) === 'pi') { i += 2; return Math.PI; }
      if (/[a-z]/.test(c)) { if (!(c in env)) fail(); i++; return env[c]; }
      var m = /^[0-9]*\.?[0-9]+(e[-+]?[0-9]+)?|^[0-9]+\./.exec(s.slice(i));
      if (!m) fail();
      i += m[0].length;
      return parseFloat(m[0]);
    }
    var v = parseExpr();
    if (i !== s.length || !isFinite(v)) fail();
    return v;
  }

  // 含字母（例如答案是 a/3）時，代兩組數值進去比較
  var ENVS = [{}, {}];
  'abcdefghijklmnoqrstuvwxyz'.split('').forEach(function (ch, k) {
    ENVS[0][ch] = 1.3 + 0.37 * k; ENVS[1][ch] = 2.9 - 0.071 * k;
  });
  function tryNum(s, env) {
    if (!s || !/[0-9a-z]/.test(s)) return null;
    try { return evaluate(s, env); } catch (e) { return null; }
  }
  function close(x, y) {
    return Math.abs(x - y) <= 1e-9 * Math.max(1, Math.abs(x), Math.abs(y));
  }
  function sameScalar(a, b) {
    if (a === b) return true;
    var vars = /[a-z]/.test(b.replace(/sqrt|pi/g, '')) || /[a-z]/.test(a.replace(/sqrt|pi/g, ''));
    var envs = vars ? ENVS : [{}];
    for (var k = 0; k < envs.length; k++) {
      var x = tryNum(a, envs[k]), y = tryNum(b, envs[k]);
      if (x === null || y === null || !close(x, y)) return false;
    }
    return true;
  }

  function splitParts(s) {
    s = s.replace(/^\((.*)\)$/, '$1');
    // 只在最外層逗號切開
    var parts = [], depth = 0, cur = '';
    for (var k = 0; k < s.length; k++) {
      var c = s[k];
      if (c === '(') depth++;
      if (c === ')') depth--;
      if (c === ',' && depth === 0) { parts.push(cur); cur = ''; } else cur += c;
    }
    parts.push(cur);
    return parts.filter(function (p) { return p !== ''; });
  }

  function matchOne(input, spec) {
    var unordered = false;
    spec = toHalfWidth(spec).trim();
    if (/^set:/i.test(spec)) { unordered = true; spec = spec.slice(4); }
    var a = normalize(input), b = normalize(spec);
    if (!a) return false;
    if (b.indexOf(',') === -1) return sameScalar(a, b);
    var pa = splitParts(a), pb = splitParts(b);
    if (pa.length !== pb.length) return false;
    if (!unordered) {
      for (var k = 0; k < pb.length; k++) if (!sameScalar(pa[k], pb[k])) return false;
      return true;
    }
    var used = pa.map(function () { return false; });
    for (var j = 0; j < pb.length; j++) {
      var hit = -1;
      for (var t = 0; t < pa.length; t++) if (!used[t] && sameScalar(pa[t], pb[j])) { hit = t; break; }
      if (hit < 0) return false;
      used[hit] = true;
    }
    return true;
  }

  function isCorrect(input, answerSpec) {
    var specs = String(answerSpec == null ? '' : answerSpec).split('|');
    for (var k = 0; k < specs.length; k++) if (specs[k].trim() && matchOne(input, specs[k])) return true;
    return false;
  }

  var api = { isCorrect: isCorrect, normalize: normalize, evaluate: evaluate };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  root.TRMLGrade = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);

function isCorrect(a, b) { return TRMLGrade.isCorrect(a, b); }

/* TRML 練習系統：Google Apps Script 後端（競速賽、個人賽、團體賽）
 * 試算表裡的工作表（執行 setup() 會自動建好、補齊欄位）：
 *   settings    項目 | 值　　　（「目前年度」決定學生頁顯示哪一年的名單）
 *   roster      隊伍 | 姓名 | 代碼 | 年度 | 學生編號
 *               代碼空白＝不需要代碼；年度空白＝目前年度；學生編號空白＝用姓名（跨年度同名就連在一起）
 *   questions   題號 | 答案 | 題型 | 圖檔 | 文字題目 | 關鍵　　（答案寫「人工:參考答案」＝老師批改的證明題；關鍵＝週四講解的核心一句，只給老師頁）
 *   sets        卷號 | 名稱 | 分鐘 | 題號 | 開放 | 交卷後顯示答案 | 開放日期 | 通關密碼 | 說明 | 賽別
 *               賽別：競速／個人／團體（空白＝競速）。個人賽的「分鐘」是每一回合的分鐘數。
 *   submissions 每次交卷一列（程式寫入）
 *   responses   每題一列（程式寫入；團體賽證明題的「得分」由老師統計頁批改）
 * 老師統計頁的密碼放在「專案設定 → 指令碼屬性」：TEACHER_KEY
 */

var SHEETS = {
  settings: ['項目', '值'],
  roster: ['隊伍', '姓名', '代碼', '年度', '學生編號', '分析密碼', '密碼已顯示'],
  questions: ['題號', '答案', '題型', '圖檔', '文字題目', '關鍵'],
  sets: ['卷號', '名稱', '分鐘', '題號', '開放', '交卷後顯示答案', '開放日期', '通關密碼', '說明', '賽別'],
  submissions: ['交卷時間', '作答編號', '卷號', '隊伍', '姓名', '第幾次', '得分', '題數', '用時秒', '開始時間', '年度', '學生編號', '賽別', '滿分', '待批改'],
  notes: ['時間', '年度', '學生編號', '隊伍', '姓名', '卷號', '題號', '難易度', '卡在哪', '想法', '照片', '分享'],
  responses: ['作答編號', '交卷時間', '卷號', '隊伍', '姓名', '第幾次', '題號', '作答', '對錯', '用時秒', '年度', '學生編號', '賽別', '得分', '照片', '批改']
};
var PHOTO_FOLDER = 'TRML 團體賽證明題照片';
// 詳解圖放在網頁的 sol/ 資料夾，檔名由題號加密鑰算出，交卷後才把檔名給學生
var SOL_SALT = '845173de456398db4aebe868';
function solPath_(qid) {
  var sig = Utilities.computeHmacSha256Signature(String(qid), SOL_SALT);
  return 'sol/' + sig.map(function (b) { return ('0' + ((b + 256) % 256).toString(16)).slice(-2); }).join('').slice(0, 16) + '.png';
}

function setup() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  Object.keys(SHEETS).forEach(function (name) {
    var sh = ss.getSheetByName(name) || ss.insertSheet(name);
    sh.getRange(1, 1, 1, SHEETS[name].length).setValues([SHEETS[name]]).setFontWeight('bold');
    sh.setFrozenRows(1);
  });
  ss.getSheetByName('questions').getRange('B:B').setNumberFormat('@');
  ss.getSheetByName('roster').getRange('C:G').setNumberFormat('@');
  ss.getSheetByName('responses').getRange('H:H').setNumberFormat('@');
  ss.getSheetByName('sets').getRange('D:D').setNumberFormat('@');
  ss.getSheetByName('sets').getRange('G:H').setNumberFormat('@');
  ss.getSheetByName('settings').getRange('B:B').setNumberFormat('@');

  var st = ss.getSheetByName('settings');
  if (!settings_()['目前年度']) st.appendRow(['目前年度', String(new Date().getFullYear())]);
  var year = year_();

  // 舊資料補欄位：沒有年度的算目前年度、沒有學生編號的用姓名、沒有賽別的算競速
  fill_('roster', 5, function (r) { return [r[3] || year, r[4] || r[1]]; }, 4);
  analysisPins_();
  fill_('submissions', 15, function (r) { return [r[10] || year, r[11] || r[4], r[12] || '競速', r[13] || r[7], r[14] || 0]; }, 11);
  fill_('responses', 16, function (r) { return [r[10] || year, r[11] || r[4], r[12] || '競速', r[13] === '' ? r[8] : r[13]]; }, 11);

  DriveApp.getRootFolder(); // 讓授權畫面一併要求雲端硬碟權限（存證明題照片用）
  var props = PropertiesService.getScriptProperties();
  if (!props.getProperty('TEACHER_KEY')) props.setProperty('TEACHER_KEY', 'trml' + Math.floor(1000 + Math.random() * 9000));
  Logger.log('目前年度：' + year);
  Logger.log('老師統計頁密碼：' + props.getProperty('TEACHER_KEY'));
}

// 把第 startCol 欄開始的幾欄補上值（只補空白，原本有值的不動）
function fill_(name, width, fn, startCol) {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(name);
  if (!sh || sh.getLastRow() < 2) return;
  var n = sh.getLastRow() - 1;
  var v = sh.getRange(2, 1, n, width).getDisplayValues();
  var k = fn(v[0]).length;
  var out = v.map(function (r) {
    if (r.join('').trim() === '') return r.slice(startCol - 1, startCol - 1 + k);
    return fn(r);
  });
  sh.getRange(2, startCol, n, out[0].length).setValues(out);
}

function rows_(name) {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(name);
  if (!sh || sh.getLastRow() < 2) return [];
  var w = Math.max(sh.getLastColumn(), (SHEETS[name] || []).length);
  var v = sh.getRange(2, 1, sh.getLastRow() - 1, w).getDisplayValues();
  return v.filter(function (r) { return r.join('').trim() !== ''; });
}

function settings_() {
  var m = {};
  rows_('settings').forEach(function (r) { if (r[0]) m[String(r[0]).trim()] = String(r[1] || '').trim(); });
  return m;
}
function year_() { return settings_()['目前年度'] || String(new Date().getFullYear()); }

function yes_(v) { return /^(y|yes|是|v|1|true|開)$/i.test(String(v).trim()); }
function kindOf_(v) { v = String(v || ''); return /個/.test(v) ? '個人' : /團/.test(v) ? '團體' : '競速'; }
function isManual_(spec) { return /^人工/.test(String(spec || '').trim()); }
function manualRef_(spec) { return String(spec || '').replace(/^人工[:：]?/, '').trim(); }

function questionMap_() {
  var m = {};
  rows_('questions').forEach(function (r) {
    m[r[0].trim()] = { qid: r[0].trim(), answer: r[1], topic: r[2], img: r[3], text: r[4], key: r[5] || '' };
  });
  return m;
}

function parseDate_(v) {
  v = String(v || '').trim().replace(/[年月]/g, '/').replace(/日/g, '').replace(/-/g, '/');
  if (!v) return null;
  var m = v.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})/) || v.match(/^()(\d{1,2})\/(\d{1,2})/);
  if (!m) return null;
  var y = m[1] ? Number(m[1]) : new Date().getFullYear();
  return new Date(y, Number(m[2]) - 1, Number(m[3]));
}

// status：open 可直接寫｜locked 要通關密碼｜scheduled 日期未到｜hidden 不顯示
function sets_() {
  var now = new Date();
  return rows_('sets').map(function (r) {
    var s = {
      id: r[0].trim(), title: r[1], minutes: Number(r[2]) || 20,
      qids: String(r[3]).split(/[,，、\s]+/).filter(String),
      open: yes_(r[4]), showAnswers: yes_(r[5]),
      openDate: parseDate_(r[6]), pass: String(r[7] || '').trim(), note: String(r[8] || '').trim(),
      kind: kindOf_(r[9])
    };
    if (s.open) s.status = 'open';
    else if (s.openDate && now < s.openDate) s.status = 'scheduled';
    else if (s.pass) s.status = 'locked';
    else if (s.openDate) s.status = 'open';
    else s.status = 'hidden';
    return s;
  });
}

function passOk_(set, pass) {
  var norm = function (x) { return String(x || '').trim().toLowerCase(); };
  return set.status === 'open' || (set.status === 'locked' && norm(pass) === norm(set.pass));
}

function publicQuestions_(set, qm) {
  return set.qids.map(function (q) {
    var x = qm[q] || { qid: q };
    var o = { qid: q, img: x.img || '', text: x.text || '' }; // 不送答案
    if (isManual_(x.answer)) o.manual = true;
    return o;
  });
}

function json_(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

function doGet(e) {
  var p = (e && e.parameter) || {};
  try {
    if (p.action === 'report') return json_(report_(p.key));
    return json_(init_());
  } catch (err) {
    return json_({ ok: false, error: String(err && err.message || err) });
  }
}

function doPost(e) {
  try {
    var body = JSON.parse(e.postData.contents);
    if (body.action === 'login') {
      var who = person_(body.team, body.name);
      if (!who) return json_({ ok: false, error: '名單上找不到這個人' });
      var okPin = pinOk_(body.team, body.name, body.pin);
      if (okPin && body.setId) {
        var cs = sets_().filter(function (x) { return x.id === body.setId; })[0];
        if (cs && cs.kind === '團體') { var cl = claim_(who, cs, true); if (!cl.ok) return json_(cl); }
      }
      return json_({ ok: okPin, needPin: who.pin !== '' });
    }
    if (body.action === 'unlock') {
      var st = sets_().filter(function (x) { return x.id === body.setId; })[0];
      if (!st || st.status === 'hidden') return json_({ ok: false, error: '找不到這份卷子' });
      if (st.status === 'scheduled') return json_({ ok: false, error: '這份卷子還沒到開放日期' });
      if (!passOk_(st, body.pass)) return json_({ ok: false, error: '通關密碼不對' });
      return json_({ ok: true, questions: publicQuestions_(st, questionMap_()) });
    }
    if (body.action === 'submit') return json_(submit_(body));
    if (body.action === 'profile') return json_(profile_(body));
    if (body.action === 'grade') return json_(grade_(body));
    if (body.action === 'note') return json_(note_(body));
    if (body.action === 'share') return json_(share_(body));
    return json_({ ok: false, error: 'unknown action' });
  } catch (err) {
    return json_({ ok: false, error: String(err && err.message || err) });
  }
}

/* ---------- 名單 ---------- */
function roster_() {
  var year = year_();
  return rows_('roster').map(function (r) {
    return { team: r[0].trim(), name: r[1].trim(), pin: String(r[2] || '').trim(),
      year: String(r[3] || '').trim() || year, id: String(r[4] || '').trim() || r[1].trim(), apin: String(r[5] || '').trim(), shown: String(r[6] || '').trim() };
  }).filter(function (p) { return p.team && p.name; });
}
function person_(team, name, year) {
  year = year || year_();
  return roster_().filter(function (p) {
    return p.year === year && p.team === String(team).trim() && p.name === String(name).trim();
  })[0] || null;
}
// 「我的分析」用的個人密碼：roster 第 F 欄，空白的自動補 4 碼亂數（清空就會重發）
// 第 G 欄記錄密碼什麼時候在交卷畫面顯示過；重發新密碼時一併清空，下次交卷再顯示一次
function analysisPins_() {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('roster');
  if (!sh || sh.getLastRow() < 2) return;
  var n = sh.getLastRow() - 1, v = sh.getRange(2, 1, n, 7).getDisplayValues(), changed = false;
  var used = {}; v.forEach(function (r) { if (r[5]) used[String(r[5]).trim()] = 1; });
  var out = v.map(function (r) {
    if (!r[0].trim() || !r[1].trim() || String(r[5]).trim()) return [r[5], r[6]];
    var p; do { p = String(1000 + Math.floor(Math.random() * 9000)); } while (used[p]);
    used[p] = 1; changed = true; return [p, ''];
  });
  if (changed) sh.getRange(2, 6, n, 2).setNumberFormat('@').setValues(out);
}
// 交卷後第一次：回傳分析密碼並記下已顯示（之後不再顯示）
function revealPin_(who) {
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('roster');
  var n = sh.getLastRow() - 1;
  if (n < 1) return null;
  if (!who.apin) analysisPins_();
  var v = sh.getRange(2, 1, n, 7).getDisplayValues(), year = year_();
  for (var i = 0; i < v.length; i++) {
    var r = v[i];
    if (r[0].trim() !== who.team || r[1].trim() !== who.name || (String(r[3]).trim() || year) !== who.year) continue;
    if (String(r[6]).trim() || !String(r[5]).trim()) return null;
    sh.getRange(i + 2, 7).setValue(Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy/MM/dd HH:mm'));
    return String(r[5]).trim();
  }
  return null;
}
function apinOk_(p, apin) {
  var norm = function (x) { return String(x || '').trim().replace(/^0+(?=.)/, ''); };
  return !!p && p.apin !== '' && norm(p.apin) === norm(apin);
}

function pinOk_(team, name, pin) {
  var p = person_(team, name);
  if (!p) return false;
  if (p.pin === '') return true;
  var norm = function (x) { return String(x || '').trim().replace(/^0+(?=.)/, ''); };
  return norm(p.pin) === norm(pin);
}

function init_() {
  var year = year_(), teams = {}, order = [];
  roster_().forEach(function (p) {
    if (p.year !== year) return;
    if (!teams[p.team]) { teams[p.team] = []; order.push(p.team); }
    teams[p.team].push(p.name);
  });
  var qm = questionMap_();
  var tz = Session.getScriptTimeZone();
  var sets = sets_().filter(function (s) { return s.status !== 'hidden'; }).map(function (s) {
    var o = { id: s.id, title: s.title, minutes: s.minutes, count: s.qids.length, status: s.status, note: s.note, kind: s.kind };
    if (s.openDate) o.openDate = Utilities.formatDate(s.openDate, tz, 'M/d');
    if (s.status === 'open') o.questions = publicQuestions_(s, qm);
    return o;
  });
  return { ok: true, year: year, teams: order.map(function (t) { return { team: t, members: teams[t] }; }), sets: sets };
}

/* ---------- 計分 ----------
 * 競速：每題 1 分。個人：兩題一回合，全對 3 分、對一題 1 分。
 * 團體：前面自動批改的每題 4 分，證明題（答案寫「人工」）每題 8 分、老師批改。 */
var TEAM_AUTO = 4, TEAM_MANUAL = 8;
function maxOf_(kind, qids, qm) {
  if (kind === '個人') return Math.ceil(qids.length / 2) * 3;
  if (kind === '團體') return qids.reduce(function (a, q) { return a + (isManual_((qm[q] || {}).answer) ? TEAM_MANUAL : TEAM_AUTO); }, 0);
  return qids.length;
}
function roundPoints_(oks) {
  var out = [];
  for (var i = 0; i < oks.length; i += 2) {
    var c = (oks[i] ? 1 : 0) + (oks[i + 1] ? 1 : 0);
    out.push(c === 2 ? 3 : c === 1 ? 1 : 0);
  }
  return out;
}

function photoFolder_() {
  var it = DriveApp.getFoldersByName(PHOTO_FOLDER);
  return it.hasNext() ? it.next() : DriveApp.createFolder(PHOTO_FOLDER);
}
function savePhotos_(list, base) {
  if (!list || !list.length) return '';
  var folder = photoFolder_();
  return list.slice(0, 3).map(function (d, i) {
    var m = String(d).match(/^data:(image\/[a-z+]+);base64,(.+)$/);
    if (!m) return '';
    var blob = Utilities.newBlob(Utilities.base64Decode(m[2]), m[1], base + '-' + (i + 1) + '.jpg');
    return folder.createFile(blob).getUrl();
  }).filter(String).join(' ');
}

// 團體賽一隊只由一人作答：第一個按「開始計時」的隊員取得這份卷子 40 分鐘，其他隊員進不去、交了也不記錄
var CLAIM_MS = 40 * 60 * 1000;
function claim_(who, set, take) {
  var props = PropertiesService.getScriptProperties(), key = 'claim|' + year_() + '|' + set.id + '|' + who.team;
  var now = Date.now(), raw = props.getProperty(key), c = null;
  try { c = raw ? JSON.parse(raw) : null; } catch (e) { c = null; }
  if (c && c.name !== who.name && now - c.t < CLAIM_MS) {
    var hm = Utilities.formatDate(new Date(c.t), Session.getScriptTimeZone(), 'HH:mm');
    return { ok: false, error: '這一隊的〈' + set.title + '〉已經由 ' + c.name + ' 在 ' + hm + ' 開始作答。一隊只交一份，請到 ' + c.name + ' 的裝置一起看題目、討論。' };
  }
  var yr = year_(), other = rows_('submissions').filter(function (r) { return r[2] === set.id && r[10] === yr && r[3] === who.team && r[4] !== who.name; })[0];
  if (other) return { ok: false, error: '這一隊的〈' + set.title + '〉已經由 ' + other[4] + ' 交過了，一隊只交一份。' };
  if (take) props.setProperty(key, JSON.stringify({ name: who.name, t: (c && c.name === who.name && now - c.t < CLAIM_MS) ? c.t : now }));
  return { ok: true };
}

function submit_(b) {
  var who = person_(b.team, b.name);
  if (!who || !pinOk_(b.team, b.name, b.pin)) return { ok: false, error: '代碼不對，請回清單重新輸入代碼後再送出' };
  var set = sets_().filter(function (s) { return s.id === b.setId; })[0];
  if (!set) return { ok: false, error: '找不到這份卷子：' + b.setId };
  if (!passOk_(set, b.setPass)) return { ok: false, error: set.status === 'scheduled' ? '這份卷子還沒到開放日期' : '這份卷子需要通關密碼' };
  if (set.kind === '團體' && !rows_('submissions').some(function (r) { return r[1] === String(b.clientId); })) {
    var cl = claim_(who, set, false); if (!cl.ok) return cl;
  }
  var qm = questionMap_(), kind = set.kind, year = year_();
  var byQ = {};
  (b.responses || []).forEach(function (r) { byQ[r.qid] = r; });

  var lock = LockService.getScriptLock();
  lock.waitLock(25000);
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var subs = rows_('submissions');
    var attemptId = String(b.clientId || Utilities.getUuid());
    var dup = subs.filter(function (r) { return r[1] === attemptId; })[0];
    var attemptNo = 1;
    subs.forEach(function (r) {
      if (r[2] !== set.id || r[10] !== year) return;
      if (kind === '團體' ? r[3] === who.team : r[11] === who.id) attemptNo++;
    });
    if (dup) attemptNo = Number(dup[5]);

    var now = new Date(), results = [], rowsOut = [], oks = [], score = 0, pending = 0;
    var secCap = set.minutes * 60 * (kind === '個人' ? Math.ceil(set.qids.length / 2) : 1);
    set.qids.forEach(function (q, i) {
      var r = byQ[q] || { answer: '', seconds: 0 };
      var spec = (qm[q] || {}).answer || '';
      var manual = isManual_(spec);
      var ans = String(r.answer || '').slice(0, manual ? 3000 : 80);
      var ok = !manual && ans !== '' && isCorrect(ans, spec);
      var pts = '', photos = '';
      if (manual) {
        pending++;
        if (!dup) photos = savePhotos_(r.photos, set.id + '-' + who.team + '-' + q + '-' + attemptNo);
      } else {
        pts = kind === '團體' ? (ok ? TEAM_AUTO : 0) : (ok ? 1 : 0);
        if (kind !== '個人') score += pts;
      }
      oks.push(ok);
      results.push({ qid: q, correct: ok, manual: manual, points: pts, sol: set.showAnswers ? solPath_(q) : null,
        expected: set.showAnswers ? (manual ? manualRef_(spec) : spec.split('|')[0].replace(/^set:/i, '')) : null });
      rowsOut.push([attemptId, now, set.id, who.team, who.name, attemptNo, q, ans, manual ? '' : (ok ? 1 : 0),
        Math.min(secCap, Math.round(Number(r.seconds) || 0)), year, who.id, kind, pts, photos, manual ? '待批改' : '']);
    });
    var rounds = null;
    if (kind === '個人') { rounds = roundPoints_(oks); score = rounds.reduce(function (a, x) { return a + x; }, 0); }
    var max = maxOf_(kind, set.qids, qm);

    if (!dup) {
      var used = Math.min(secCap, Math.round(Number(b.usedSec) || 0));
      ss.getSheetByName('submissions').appendRow([now, attemptId, set.id, who.team, who.name, attemptNo, score, set.qids.length, used,
        b.startedAt ? new Date(b.startedAt) : '', year, who.id, kind, max, pending]);
      var rs = ss.getSheetByName('responses');
      rs.getRange(rs.getLastRow() + 1, 1, rowsOut.length, rowsOut[0].length).setValues(rowsOut);
      var apin = revealPin_(who);
    }
    return { ok: true, apin: apin || null, notes: myNotes_(who, set.qids), shared: set.showAnswers ? sharedNotes_(set.qids, who.id) : {}, kind: kind, score: score, max: max, total: set.qids.length, pending: pending, rounds: rounds,
      attemptNo: attemptNo, results: results, showAnswers: set.showAnswers };
  } finally {
    lock.releaseLock();
  }
}

/* ---------- 讀資料（老師頁與個人分析共用） ---------- */
function subsAll_() {
  return rows_('submissions').map(function (r) {
    return { time: r[0], attemptId: r[1], setId: r[2], team: r[3], name: r[4], attemptNo: Number(r[5]), score: Number(r[6]),
      total: Number(r[7]), usedSec: Number(r[8]), year: r[10], sid: r[11] || r[4], kind: kindOf_(r[12]), max: Number(r[13]) || Number(r[7]),
      pending: Number(r[14]) || 0 };
  });
}
function respsAll_() {
  return rows_('responses').map(function (r) {
    return { attemptId: r[0], setId: r[2], team: r[3], name: r[4], attemptNo: Number(r[5]), qid: r[6], answer: r[7],
      correct: r[8] === '1', seconds: Number(r[9]), year: r[10], sid: r[11] || r[4], kind: kindOf_(r[12]),
      points: r[13] === '' ? null : Number(r[13]), photos: r[14] || '', graded: r[15] || '' };
  });
}

// 學生看自己的分析：只送自己的紀錄，再加上同年度全體的題型平均（拿來比較）
function profile_(b) {
  var who = person_(b.team, b.name);
  if (who && !who.apin) { analysisPins_(); who = person_(b.team, b.name); }
  if (!apinOk_(who, b.apin)) return { ok: false, error: '分析密碼不對。分析密碼是老師另外發給每個人的，不是小組代碼。' };
  var subs = subsAll_(), resps = respsAll_(), qm = questionMap_();
  var myTeams = {};
  roster_().forEach(function (p) { if (p.id === who.id) myTeams[p.year + '|' + p.team] = 1; });
  var mySubs = subs.filter(function (s) {
    return s.kind === '團體' ? myTeams[s.year + '|' + s.team] : s.sid === who.id;
  });
  var myIds = {}; mySubs.forEach(function (s) { myIds[s.attemptId] = 1; });
  var myResps = resps.filter(function (r) { return myIds[r.attemptId]; }).map(function (r) {
    return { attemptId: r.attemptId, setId: r.setId, qid: r.qid, answer: r.answer, correct: r.correct, seconds: r.seconds,
      kind: r.kind, attemptNo: r.attemptNo, year: r.year, points: r.points, team: r.team };
  });
  var qinfo = {};
  var titles = {}, showA = {}; sets_().forEach(function (s) { titles[s.id] = s.title; showA[s.id] = s.showAnswers; });
  myResps.forEach(function (r) {
    var q = qm[r.qid] || {}, o = qinfo[r.qid] || (qinfo[r.qid] = { topic: q.topic || '', img: q.img || '' });
    if (showA[r.setId] && !o.sol) o.sol = solPath_(r.qid);
  });
  return { ok: true, me: { name: who.name, team: who.team, year: who.year, id: who.id },
    subs: mySubs.map(function (s) { s.title = titles[s.setId] || s.setId; return s; }), resps: myResps, qinfo: qinfo,
    notes: myNotes_(who, Object.keys(qinfo)), shared: sharedNotes_(Object.keys(qinfo).filter(function (q) { return qinfo[q].sol; }), who.id),
    cls: classStats_(resps, qm, who.year) };
}

function classStats_(resps, qm, year) {
  var topics = {}, speed = { n: 0, sec: 0 };
  resps.forEach(function (r) {
    if (r.year !== year || r.attemptNo !== 1 || r.kind === '團體') return;
    var t = (qm[r.qid] || {}).topic || '未分類';
    var x = topics[t] || (topics[t] = { n: 0, ok: 0, sec: 0 });
    x.n++; if (r.correct) x.ok++; x.sec += r.seconds;
    if (r.kind === '競速') { speed.n++; speed.sec += r.seconds; }
  });
  return { year: year, topics: topics, speedSec: speed.n ? speed.sec / speed.n : null };
}

function teacherOk_(key) {
  var real = PropertiesService.getScriptProperties().getProperty('TEACHER_KEY');
  return real && String(key) === real;
}

function report_(key) {
  if (!teacherOk_(key)) return { ok: false, error: '密碼不對' };
  analysisPins_();
  var qm = questionMap_();
  return {
    ok: true, year: year_(),
    sets: sets_().map(function (s) { return { id: s.id, title: s.title, minutes: s.minutes, qids: s.qids, kind: s.kind, status: s.status }; }),
    questions: Object.keys(qm).map(function (k) { var q = qm[k]; q.sol = solPath_(k); return q; }),
    roster: roster_().map(function (p) { return { team: p.team, name: p.name, year: p.year, id: p.id, apin: p.apin, shown: p.shown }; }),
    submissions: subsAll_(),
    responses: respsAll_(),
    notes: notesAll_().map(function (n) { delete n.row; return n; })
  };
}

// 老師批改團體賽證明題：寫回 responses 的得分，再重算那次交卷的總分
function grade_(b) {
  if (!teacherOk_(b.key)) return { ok: false, error: '密碼不對' };
  var pts = Number(b.points);
  if (!(pts >= 0 && pts <= TEAM_MANUAL)) return { ok: false, error: '分數要在 0～' + TEAM_MANUAL + ' 之間' };
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var rs = ss.getSheetByName('responses');
    var n = rs.getLastRow() - 1;
    if (n < 1) return { ok: false, error: '找不到這一題' };
    var v = rs.getRange(2, 1, n, 16).getDisplayValues();
    var hit = -1, total = 0, pending = 0;
    v.forEach(function (r, i) {
      if (r[0] !== b.attemptId) return;
      if (r[6] === b.qid) { hit = i; r[13] = String(pts); r[15] = '已批改' + (b.note ? '：' + String(b.note).slice(0, 200) : ''); }
      if (r[13] !== '') total += Number(r[13]); else if (/待批改/.test(r[15])) pending++;
    });
    if (hit < 0) return { ok: false, error: '找不到這一題' };
    rs.getRange(hit + 2, 14).setValue(pts);
    rs.getRange(hit + 2, 16).setValue(v[hit][15]);
    var sh = ss.getSheetByName('submissions');
    var sv = sh.getRange(2, 1, sh.getLastRow() - 1, 2).getDisplayValues();
    for (var i = 0; i < sv.length; i++) {
      if (sv[i][1] === b.attemptId) {
        sh.getRange(i + 2, 7).setValue(total);
        sh.getRange(i + 2, 15).setValue(pending);
        break;
      }
    }
    return { ok: true, total: total, pending: pending };
  } finally {
    lock.releaseLock();
  }
}

/* ---------- 學生對每題的回饋：難易度、卡在哪、想法／另解（照片選填） ---------- */
var STUCK = ['看不懂題目', '沒有想法', '方法對但算錯', '粗心', '看完詳解還是不懂'];
function notesSheet_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet(), sh = ss.getSheetByName('notes');
  if (!sh) {
    sh = ss.insertSheet('notes');
    sh.getRange(1, 1, 1, SHEETS.notes.length).setValues([SHEETS.notes]).setFontWeight('bold');
    sh.setFrozenRows(1);
    sh.getRange('J:J').setNumberFormat('@');
  }
  return sh;
}
function notesAll_() {
  notesSheet_();
  var sh = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('notes');
  if (sh.getLastRow() < 2) return [];
  return sh.getRange(2, 1, sh.getLastRow() - 1, 12).getDisplayValues().map(function (r, i) {
    return { row: i + 2, time: r[0], year: r[1], sid: r[2], team: r[3], name: r[4], setId: r[5], qid: r[6], diff: r[7],
      stuck: r[8] ? r[8].split('、') : [], text: r[9], photos: r[10] ? r[10].split(/\s+/) : [], shared: yes_(r[11]) };
  }).filter(function (n) { return n.qid; });
}
function myNotes_(who, qids) {
  var want = {}; qids.forEach(function (q) { want[q] = 1; });
  var out = {};
  notesAll_().forEach(function (n) {
    if (n.sid === who.id && want[n.qid]) out[n.qid] = { diff: n.diff, stuck: n.stuck, text: n.text, nphotos: n.photos.length, shared: n.shared, time: n.time };
  });
  return out;
}
function driveId_(url) { var m = String(url).match(/[-\w]{25,}/); return m ? m[0] : ''; }
function sharedNotes_(qids, exceptSid) {
  var want = {}; qids.forEach(function (q) { want[q] = 1; });
  var out = {};
  notesAll_().forEach(function (n) {
    if (!n.shared || !want[n.qid] || n.sid === exceptSid) return;
    (out[n.qid] = out[n.qid] || []).push({ name: n.name, text: n.text,
      photos: n.photos.map(function (u) { return 'https://drive.google.com/thumbnail?id=' + driveId_(u) + '&sz=w1200'; }) });
  });
  return out;
}
function note_(b) {
  var who = person_(b.team, b.name);
  if (!who || !(pinOk_(b.team, b.name, b.pin) || apinOk_(who, b.apin))) return { ok: false, error: '代碼不對，存不進去' };
  var qid = String(b.qid || '').trim();
  var did = respsAll_().some(function (r) {
    return r.qid === qid && (r.kind === '團體' ? r.team === who.team && r.year === who.year : r.sid === who.id);
  });
  if (!did) return { ok: false, error: '交過這題才能寫回饋' };
  var diff = ['簡單', '剛好', '難'].indexOf(b.diff) >= 0 ? b.diff : '';
  var stuck = (b.stuck || []).filter(function (x) { return STUCK.indexOf(x) >= 0; }).join('、');
  var text = String(b.text || '').slice(0, 2000);
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var sh = notesSheet_(), old = notesAll_().filter(function (n) { return n.sid === who.id && n.qid === qid; })[0];
    var photos = old ? old.photos : [];
    if (b.clearPhotos) photos = [];
    if (b.photos && b.photos.length) photos = photos.concat(String(savePhotos_(b.photos.slice(0, 2), 'note-' + who.id + '-' + qid)).split(' ').filter(String)).slice(-2);
    var row = [Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy/MM/dd HH:mm'), who.year, who.id, who.team, who.name,
      String(b.setId || ''), qid, diff, stuck, text, photos.join(' '), old && old.shared ? 'Y' : ''];
    if (old) sh.getRange(old.row, 1, 1, 12).setValues([row]);
    else sh.appendRow(row);
    return { ok: true, note: { diff: diff, stuck: stuck ? stuck.split('、') : [], text: text, nphotos: photos.length, shared: !!(old && old.shared), time: row[0] } };
  } finally {
    lock.releaseLock();
  }
}
// 老師把好的另解分享給之後交過這題的人（照片會改成知道連結的人可看；學校帳號若不允許就只分享文字）
function share_(b) {
  if (!teacherOk_(b.key)) return { ok: false, error: '密碼不對' };
  var n = notesAll_().filter(function (x) { return x.sid === b.sid && x.qid === b.qid && x.year === b.year; })[0];
  if (!n) return { ok: false, error: '找不到這則回饋' };
  var on = !!b.on, warn = '';
  if (on) n.photos.forEach(function (u) {
    try { DriveApp.getFileById(driveId_(u)).setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); }
    catch (e) { warn = '照片沒辦法公開（可能是學校帳號的限制），同學只看得到文字。'; }
  });
  SpreadsheetApp.getActiveSpreadsheet().getSheetByName('notes').getRange(n.row, 12).setValue(on ? 'Y' : '');
  return { ok: true, shared: on, warn: warn };
}
